perl -e '
# The ZIP says file is 33 bytes, starts PASSWORD=8XDP5Q2RT9Z (20 bytes)
# + 13 more bytes + newline
# strings showed: PASSWORD=8XDP5Q2RT9Z and then \K7VB3BV4WW54
# K7VB3BV4WW54 = 12 chars, plus newline = 13 bytes
# Complete password candidate: 8XDP5Q2RT9ZK7VB3BV4WW54

# Verify with CRC32 (expected from ZIP: 0xb0725dc4)
use String::CRC32;
my $content = "PASSWORD=8XDP5Q2RT9ZK7VB3BV4WW54\n";
printf "Content length: %d\n", length($content);
printf "CRC32: 0x%08x\n", crc32($content);
printf "Expected:  0x%08x\n", 0xb0725dc4;
' 2>/dev/null || echo "String::CRC32 not available"

# Manual CRC32 calculation
perl -e '
sub crc32 {
    my $data = shift;
    my @crc_table;
    for my $i (0..255) {
        my $c = $i;
        for (1..8) { $c = ($c & 1) ? (0xEDB88320 ^ ($c >> 1)) : ($c >> 1); }
        $crc_table[$i] = $c;
    }
    my $crc = 0xFFFFFFFF;
    for my $byte (unpack("C*", $data)) {
        $crc = $crc_table[($crc ^ $byte) & 0xFF] ^ ($crc >> 8);
    }
    return $crc ^ 0xFFFFFFFF;
}

my $candidate = "PASSWORD=8XDP5Q2RT9ZK7VB3BV4WW54\n";
printf "Length: %d\n", length($candidate);
printf "CRC32: 0x%08x\n", crc32($candidate);
printf "Expected: 0x%08x\n", 0xb0725dc4;
printf "Match: %s\n", crc32($candidate) == 0xb0725dc4 ? "YES!" : "NO";
'
